/** Ordered occurrences, contraction discharges and actual nested import provenance. */
public final class ContextUniversalCompoundOccurrencesRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static Snapshot bind(boolean x,String s)throws Exception{return ContextPrivateWitnessPoolRunner.bind(x,s);}
    static Result receiver(Snapshot x,Snapshot b,Packet p,Exchange e){Result r=ContextUniversalCompoundConsumerRunner.consume(x,b,p,null,e,16,16,WORK);require(r.closed,r.reason);return r;}
    static Exchange exchange(Snapshot x,List<Snapshot> cuts,Packet p,Map<Cut,PrivatePool> pools){return ContextUniversalCompoundConsumerRunner.exchange(x,cuts,p,pools);}
    static ResidualProof residual(Exchange e,String a,String b){return ContextUniversalCompoundCompletionRunner.residual(e,a,b);}
    static Receipt yes(Capture c){require(c.captured&&c.output!=null,c.reason);ContextUniversalCompoundOccurrences.check(c.output,ContextGroundProductionRounds.budget(WORK));Set<Integer> all=new HashSet<>(c.output.consumed.keySet());for(List<Integer> group:c.output.remaining)for(int i:group)require(all.add(i),"original typed slot appears exactly once");require(all.size()==c.output.producer.clause.literals.size(),"all original slots accounted for");return c.output;}
    static void no(Capture c,String why){require(!c.captured&&c.output==null,why+": "+c.reason);}
    interface Action{void run()throws Exception;}
    static void reject(Action a,String why)throws Exception{boolean refused=false;try{a.run();}catch(IllegalStateException|IllegalArgumentException|UnsupportedOperationException expected){refused=true;}require(refused,why);}
    static int slot(Proof p,String predicate){return ContextUniversalCompoundCompletionRunner.slot(p,predicate);}
    static int position(Residual p,String predicate){for(int i=0;i<p.literals.size();++i)if(p.literals.get(i).predicate.equals(predicate))return i;throw new AssertionError(predicate);}
    static Exchange next(Snapshot x,List<Snapshot> cuts,Packet p,Exchange e){Map<Cut,Result> results=new LinkedHashMap<>();results.put(Cut.of(x),receiver(x,null,p,e));for(Snapshot a:cuts)results.put(Cut.of(a),receiver(x,a,p,e));return ContextUniversalCompoundExchangeRunner.yes(ContextUniversalCompoundExchangeRunner.collect(x,p,results,16));}
    static void contraction(boolean signed)throws Exception {
        Snapshot x=bind(true,"!pair(1,1);"),a=bind(false,"!@x @y pair(x,y)&&b(x)&&b(y)&&c(x)->"+(signed?"~":"")+"r(y);"),b=bind(false,"!safe(1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);Exchange e=exchange(x,Arrays.asList(a,b),p,Collections.emptyMap());ResidualProof c=e.clauses.stream().filter(q->q.clause.literals.size()==3).findFirst().get();Result r=receiver(x,b,p,e);Receipt out=yes(ContextUniversalCompoundOccurrences.capture(e,c,r,WORK));require(out.producer.clause.literals.size()==5&&out.resolutions.size()==1&&out.imports.isEmpty(),"actual original five-literal contraction history");require(out.consumed.size()==1&&out.consumed.containsKey(slot(out.producer,"pair")),"pair donor discharges actual original pivot");List<Integer> merged=out.remaining.get(position(c.clause,"b"));require(merged.size()==2&&merged.stream().allMatch(i->out.producer.clause.literals.get(i).predicate.equals("b")),"both original b occurrences retained in merged residual slot");require(out.support==c.support&&out.support.depth==1&&out.support.sources.size()==2,"no new grade or Source during tracing");
        Resolution step=out.resolutions.get(0);SignedResolution direct=ContextUniversalInputResiduals.resolveSignedUnitOccurrences(step.proof.unit.clause,step.proof.horn.clause,step.proof.pivot,()->{});require(direct.occurrences.get(position(direct.clause,"b")).size()==2&&ContextUniversalInputResiduals.sameOrdered(direct.clause,c.clause,()->{}),"mapping uses actual principal signed unifier and output order");require(ContextUniversalInputResiduals.sameOrdered(direct.clause,ContextUniversalInputResiduals.resolveSignedUnit(step.proof.unit.clause,step.proof.horn.clause,step.proof.pivot,()->{}),()->{}),"old signed result unchanged");
        java.lang.reflect.Field mapping=SignedResolution.class.getDeclaredField("occurrences");mapping.setAccessible(true);List<List<Integer>> saved=step.mapping.occurrences;List<List<Integer>> forged=new ArrayList<>(saved);forged.set(position(c.clause,"b"),Collections.singletonList(saved.get(position(c.clause,"b")).get(0)));mapping.set(step.mapping,forged);reject(()->ContextUniversalCompoundOccurrences.check(out,()->{}),"checker rejects mapping that silently drops a contracted original occurrence");mapping.set(step.mapping,saved);reject(()->out.resolutions.clear(),"resolution list immutable");reject(()->step.discharged.clear(),"actual discharge groups immutable");
        reject(()->out.remaining.clear(),"remaining partition immutable");reject(()->merged.clear(),"nested occurrence group immutable");reject(()->out.consumed.clear(),"consumed evidence immutable");reject(()->direct.occurrences.get(0).clear(),"resolution occurrence groups immutable");no(ContextUniversalCompoundOccurrences.capture(e,c,r,1),"work exhaustion returns no receipt");reject(()->ContextUniversalCompoundOccurrences.check(out,ContextGroundProductionRounds.budget(1)),"independent work cap");
    }
    static void mergedDischargeAndImports()throws Exception {
        Snapshot x=bind(true,"!pair(1,1);"),a=bind(false,"!@x @y pair(x,y)&&b(x)&&b(y)&&c(x)->r(y);"),b=bind(false,"!b(1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);List<Snapshot> cuts=Arrays.asList(a,b);Exchange e=exchange(x,cuts,p,Collections.emptyMap());Exchange imported=next(x,cuts,p,e);ResidualProof c=residual(imported,"c","r");Receipt out=yes(ContextUniversalCompoundOccurrences.capture(imported,c,receiver(x,b,p,imported),WORK));require(out.imports.size()==1&&out.resolutions.size()==2&&out.consumed.size()==3,"one real import plus resolution of merged b discharges three original slots total");Resolution last=out.resolutions.get(1);require(last.discharged.size()==2&&last.discharged.stream().allMatch(i->out.consumed.get(i)==last.proof.unit),"one actual b proof discharges both contracted original b occurrences");Hop hop=out.imports.get(0);require(hop.owner.compounds==hop.exchange&&hop.exchange.clauses.contains(hop.imported)&&hop.proof.compound==hop.imported,"actual owning import pointers retained");require(out.support.depth==2&&out.support.sources.size()==3,"real imported history grade/Sources unchanged");
        Exchange twice=next(x,cuts,p,imported);ResidualProof second=residual(twice,"c","r");Receipt nested=yes(ContextUniversalCompoundOccurrences.capture(twice,second,receiver(x,b,p,twice),WORK));require(nested.imports.size()>=2&&nested.consumed.equals(out.consumed)&&nested.remaining.equals(out.remaining)&&nested.support.equals(out.support),"multiple authentic imports preserve original slots, parents and support");
        java.lang.reflect.Field f=Receipt.class.getDeclaredField("remaining");f.setAccessible(true);List<List<Integer>> actual=out.remaining;List<List<Integer>> missing=new ArrayList<>(actual);missing.set(0,Collections.emptyList());f.set(out,missing);reject(()->ContextUniversalCompoundOccurrences.check(out,()->{}),"checker refuses missing original occurrence");f.set(out,actual);
        java.lang.reflect.Field consumed=Receipt.class.getDeclaredField("consumed");consumed.setAccessible(true);Map<Integer,Proof> saved=out.consumed;Map<Integer,Proof> wrong=new LinkedHashMap<>(saved);wrong.put(last.discharged.get(0),out.producer);consumed.set(out,wrong);reject(()->ContextUniversalCompoundOccurrences.check(out,()->{}),"checker refuses replacement of one duplicate-slot donor");consumed.set(out,saved);
        java.lang.reflect.Field imports=Receipt.class.getDeclaredField("imports");imports.setAccessible(true);List<Hop> history=out.imports;imports.set(out,Collections.emptyList());reject(()->ContextUniversalCompoundOccurrences.check(out,()->{}),"checker refuses omitted actual import hop");imports.set(out,history);
        // Equal clauses with another order cannot identify literal positions.
        java.lang.reflect.Constructor<Residual> ctor=Residual.class.getDeclaredConstructor(List.class,Runnable.class);ctor.setAccessible(true);List<org.kanger.ContextUniversalInputResiduals.Literal> reverse=new ArrayList<>(c.clause.literals);Collections.reverse(reverse);Residual permuted=ctor.newInstance(reverse,(Runnable)()->{});require(c.clause.equivalent(permuted,()->{})&&!ContextUniversalInputResiduals.sameOrdered(c.clause,permuted,()->{}),"alpha/permutation equivalence is deliberately insufficient for occurrence indexing");
        Proof q=ContextUniversalCompoundCompletionRunner.unit(out.receiver,"b",true);SignedResolution empty=ContextUniversalInputResiduals.resolveSignedUnitOccurrences(q.clause,ContextUniversalInputResiduals.schema(ContextUniversalNativeRows.inspect(x,bind(false,"!~b(1);"),64,WORK).rows.stream().filter(row->row.original.source.localX==false).findFirst().get().parts.get(0).clause,()->{}),0,()->{});require(empty.clause==null&&empty.occurrences.isEmpty(),"empty signed resolution has no surviving occurrence groups");
    }
    static void multipleGroupsAndSourceGrades()throws Exception {
        Snapshot x=bind(true,"!p(1); !q(1);"),a=bind(false,"!@x @y p(x)&&q(y)&&b(x)&&b(1)&&c(x)&&c(y)->r(y);"),b=bind(false,"!safe(1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);Exchange e=exchange(x,Arrays.asList(a,b),p,Collections.emptyMap());ResidualProof c=e.clauses.stream().filter(q->q.clause.literals.size()==3&&q.support.sources.size()==3).findFirst().get();Receipt out=yes(ContextUniversalCompoundOccurrences.capture(e,c,receiver(x,b,p,e),WORK));require(out.producer.clause.literals.size()==7&&out.resolutions.size()==2&&out.consumed.size()==2,"all seven original occurrences retained through successive checked substitutions");require(out.remaining.stream().filter(g->g.size()==2).count()==2&&out.remaining.get(position(c.clause,"b")).size()==2&&out.remaining.get(position(c.clause,"c")).size()==2,"two independently merged groups retain both original positions");
        Snapshot sx=bind(true,"!anchor(1); !@u p(u);"),sa=bind(false,"!@x p(x)&&b(x)->r(x);"),loop=bind(false,"!@u p(u)->p(u);"),group=ContextProductionNativeBinding.trusted("own",Arrays.asList(sa,loop),WORK),sb=bind(false,"!safe(1);");Packet sp=ContextPrivateWitnessPoolRunner.common(sx);Exchange se=exchange(sx,Arrays.asList(group,sb),sp,Collections.emptyMap());Result sr=receiver(sx,sb,sp,se);int seen=0;for(ResidualProof q:se.clauses){Receipt trace=yes(ContextUniversalCompoundOccurrences.capture(se,q,sr,WORK));require(trace.support==q.support&&trace.support.depth==(trace.support.sources.size()==2?1:2),"each Source alternative preserves its actual grade, no subset pruning/reset");++seen;}require(seen==2,"both base and Source-superset histories traced");
    }
    static void framesOriginsAndRoots()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@u @v a(u,1)&&b(u,v)->r(u,v);"),a=bind(false,"!$u a(u,1);"),b=bind(false,"!safe(1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);PrivatePool pool=ContextWitnessResultTransport.privatePool(p,x,a,WORK);Exchange e=exchange(x,Arrays.asList(a,b),p,Collections.singletonMap(pool.cut,pool));ResidualProof c=e.clauses.stream().filter(q->!q.clause.origins.isEmpty()).findFirst().get();Result r=receiver(x,b,p,e);Receipt out=yes(ContextUniversalCompoundOccurrences.capture(e,c,r,WORK));require(out.producer.original!=null&&out.resolutions.get(0).proof.unit.input!=null&&out.support.sources.containsAll(c.clause.origins.stream().map(o->o.source).collect(java.util.stream.Collectors.toSet())),"actual private seed Item/Support remains in original binding history");
        ConstraintBarrier barrier=ContextUniversalCompoundExchangeRunner.barrier(p,e.checks);Exchange rebased=ContextUniversalCompoundExchange.rebase(e,barrier,WORK);Receipt rebase=yes(ContextUniversalCompoundOccurrences.capture(rebased,c,receiver(x,b,barrier.packet,rebased),WORK));require(rebase.producer==out.producer&&rebase.remaining.equals(out.remaining)&&rebase.support==out.support,"actual historical rebase changes no occurrence/grade/Source");
        Result plain=ContextUniversalCompoundExchangeRunner.close(x,b,p,null,null);no(ContextUniversalCompoundOccurrences.capture(e,c,plain,WORK),"receiver without actual compound exchange");Exchange other=exchange(x,Arrays.asList(a,b),p,Collections.singletonMap(pool.cut,pool));no(ContextUniversalCompoundOccurrences.capture(other,c,r,WORK),"equal different carrier cannot replace input");ResidualProof foreign=ContextUniversalCompoundExchangeRunner.forgedProof(c.owner,c.owner.proofs.stream().filter(q->q.clause!=null&&q.support.sources.stream().noneMatch(s->s.localX)).findFirst().get());no(ContextUniversalCompoundOccurrences.capture(e,foreign,r,WORK),"authentic foreign proof outside capsule inventory refused");
        ResidualProof raw=e.clauses.stream().filter(q->q.support.depth==0).findFirst().get();Receipt root=yes(ContextUniversalCompoundOccurrences.capture(e,raw,r,WORK));require(root.consumed.isEmpty()&&root.resolutions.isEmpty()&&root.remaining.stream().allMatch(g->g.size()==1),"raw common-X root has a complete occurrence partition but no consumed-donor completion authority");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("compound-occurrences-").toString());contraction(false);contraction(true);mergedDischargeAndImports();multipleGroupsAndSourceGrades();framesOriginsAndRoots();System.out.println("CONTEXT_UNIVERSAL_COMPOUND_OCCURRENCES_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
